    id: row.id,
    agent: "opencode",
    alias: entry.alias,
    title: row.title || row.id,
    created_at: formatTimestamp(row.time_created),
    updated_at: formatTimestamp(row.time_updated),
    message_count: row.message_count,
    storage: "db" as const,
    parentSessionId: row.parent_id ?? undefined,
  }));
